CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, github_id TEXT NOT NULL UNIQUE, github_login TEXT NOT NULL UNIQUE, avatar_url TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS api_keys (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, key_prefix TEXT NOT NULL, key_hash TEXT NOT NULL UNIQUE, label TEXT NOT NULL DEFAULT 'default', status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_used_at TEXT, revoked_at TEXT, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS sponsor_entitlements (github_id TEXT PRIMARY KEY, github_login TEXT NOT NULL, tier_id TEXT NOT NULL, tier_name TEXT NOT NULL, status TEXT NOT NULL, requests_per_day INTEGER NOT NULL, queue_priority INTEGER NOT NULL, sponsorship_updated_at TEXT NOT NULL, expires_at TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS webhook_events (delivery_id TEXT PRIMARY KEY, event_type TEXT NOT NULL, action TEXT NOT NULL, received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, processed_at TEXT, payload_json TEXT NOT NULL);
